      ko: "가족과 시설 운영자를 위한 전문 컨설팅",
      hy: "Մասնագիտական ուղեկցում ընտանիքների և խնամքի տրամադրողների համար",
      ru: "Экспертная помощь семьям и владельцам пансионатов",
      ar: "إرشاد خبير للعائلات ومقدمي الرعاية",
