      hy: "Չքայլող, հաճախակի շրջելու, վերամբարձի կամ 2 անձի տեղափոխման կարիք, կամ հոսպիսային խնամք։",
      ru: "Маломобильный/лежачий, требуются повороты, подъемник Хойера или помощь 2 человек, либо хосписный уход.",
