      ar: "4. التعديلات والتواصل",
      fa: "۴. تغییرات و تماس",
      hi: "4. बदलाव और संपर्क",
      pa: "4. ਤਬਦੀਲੀਆਂ ਅਤੇ ਸੰਪਰਕ",
      ja: "4. 規約の改定およびお問い合わせ",
