      ko: "5. 이용 중인 외부 기술 서비스",
      hy: "5. Մեր կողմից օգտագործվող ծառայությունները",
      ru: "5. Используемые сервисы",
      ar: "5. الخدمات التي نستخدمها",
      fa: "۵. خدماتی که استفاده می‌کنیم",
